function normalizeTags(value: unknown): string[] {
  if (Array.isArray(value)) {
    return value.map(String).map((tag) => tag.trim()).filter(Boolean);
  }
  if (typeof value === 'string') {
    return value.split(',').map((tag) => tag.trim()).filter(Boolean);
  }
  return [];
}

async function markdownFiles(directory: string): Promise<string[]> {
  let entries;
  try {
    entries = await fs.readdir(directory, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
      throw new Error(`Content directory does not exist: ${directory}`);
    }
    throw error;
  }

  const files = await Promise.all(entries.map(async (entry) => {
    const entryPath = path.join(directory, entry.name);
    if (entry.isDirectory()) return markdownFiles(entryPath);
    return entry.isFile() && /\.md$/i.test(entry.name) ? [entryPath] : [];
  }));
  return files.flat().sort();
}

async function fileExists(filePath: string): Promise<boolean> {
  try {
    return (await fs.stat(filePath)).isFile();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return false;
    throw error;
  }
}

function lookup(context: TemplateContext, key: string): unknown {
  if (key === 'this' || key === '.') return context.this ?? context;
  return key.split('.').reduce<unknown>((value, part) => {
    if (value && typeof value === 'object') return (value as TemplateContext)[part];
    return undefined;
  }, context);
}

function renderTemplate(
  template: string,
  context: TemplateContext,
  partials: Map<string, string>,
  partialStack: string[] = [],
): string {
  let rendered = template.replace(/{{>\s*([^\s}]+)\s*}}/g, (_match, name: string) => {
    const partial = partials.get(name);
    if (partial === undefined) throw new Error(`Unknown partial: ${name}`);
    if (partialStack.includes(name)) throw new Error(`Circular partial include: ${[...partialStack, name].join(' -> ')}`);
    return renderTemplate(partial, context, partials, [...partialStack, name]);
  });

  rendered = rendered.replace(/{{#if\s+([^\s}]+)\s*}}([\s\S]*?){{\/if}}/g, (_match, key: string, body: string) => {
    return lookup(context, key) ? renderTemplate(body, context, partials, partialStack) : '';
  });
  rendered = rendered.replace(/{{#each\s+([^\s}]+)\s*}}([\s\S]*?){{\/each}}/g, (_match, key: string, body: string) => {
    const values = lookup(context, key);
    if (!Array.isArray(values)) return '';
    return values.map((value) => renderTemplate(body, { ...context, this: value }, partials, partialStack)).join('');
  });
  rendered = rendered.replace(/{{{\s*([^{}]+?)\s*}}}/g, (_match, key: string) => String(lookup(context, key) ?? ''));
  return rendered.replace(/{{\s*([^#/>][^{}]*?)\s*}}/g, (_match, key: string) => {
    return escapeHtml(String(lookup(context, key.trim()) ?? ''));
  });
}

async function loadPartials(directory: string): Promise<Map<string, string>> {
  const partials = new Map<string, string>();
  let entries;
  try {
    entries = await fs.readdir(directory, { withFileTypes: true });
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return partials;
    throw error;
  }

  await Promise.all(entries.map(async (entry) => {
    const filePath = path.join(directory, entry.name);
    if (entry.isDirectory()) {
      const nested = await loadPartials(filePath);
      for (const [name, contents] of nested) partials.set(`${entry.name}/${name}`, contents);
    } else if (entry.isFile() && entry.name.endsWith('.hbs')) {
      const contents = await fs.readFile(filePath, 'utf8');
      partials.set(entry.name, contents);
      partials.set(entry.name.replace(/\.hbs$/i, ''), contents);
    }
  }));
  return partials;
}

function templatePath(directory: string, name: unknown, kind: 'template' | 'layout'): string | undefined {
  if (typeof name !== 'string' || !name.trim()) return undefined;
  const baseDirectory = kind === 'layout' ? path.join(directory, 'layouts') : directory;
  const relativeName = name.trim().endsWith('.hbs') ? name.trim() : `${name.trim()}.hbs`;
  const resolved = path.resolve(baseDirectory, relativeName);
  if (resolved !== baseDirectory && !resolved.startsWith(`${baseDirectory}${path.sep}`)) {
    throw new Error(`Invalid ${kind} path: ${name}`);
  }
  return resolved;
}

function pageTemplate(metadata: PageMetadata, body: string): string {
  const title = escapeHtml(metadata.title);
  const date = metadata.date
    ? `<time datetime="${escapeHtml(metadata.date)}">${escapeHtml(metadata.date)}</time>`
    : '';
  const tags = metadata.tags.length
    ? `<ul class="tags">${metadata.tags.map((tag) => `<li>${escapeHtml(tag)}</li>`).join('')}</ul>`
    : '';

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${title}</title>
</head>
<body>
  <nav><a href="/index.html">Home</a></nav>
  <main>
    <article>
      <header><h1>${title}</h1>${date}${tags}</header>
      ${body}
    </article>
  </main>
</body>
</html>
`;
}

function indexTemplate(pages: GeneratedPage[]): string {
  const items = pages.map((page) => {
    const date = page.date ? ` <time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
    return `<li><a href="${escapeHtml(page.url)}">${escapeHtml(page.title)}</a>${date}</li>`;
  }).join('\n      ');

  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Pages</title>
</head>
<body>
  <main>
    <h1>Pages</h1>
    <ul>
      ${items}

